-- Authoritative v0 schema from Agent e1677c4; no generated database bytes.
PRAGMA application_id=1380732977;
CREATE TABLE IF NOT EXISTS preview_sessions(session_uuid TEXT PRIMARY KEY,device TEXT NOT NULL,vehicle TEXT NOT NULL,payload_session TEXT NOT NULL,manifest_generation INTEGER NOT NULL,manifest BLOB NOT NULL,record_count INTEGER NOT NULL,receipt_count INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS preview_claims(device TEXT NOT NULL,vehicle TEXT NOT NULL,payload_session TEXT NOT NULL,lane TEXT NOT NULL,session_uuid TEXT NOT NULL,PRIMARY KEY(device,vehicle,payload_session));
CREATE TABLE IF NOT EXISTS preview_sources(source_uuid TEXT PRIMARY KEY,session_uuid TEXT NOT NULL REFERENCES preview_sessions(session_uuid),segment_index INTEGER NOT NULL,source_path TEXT NOT NULL UNIQUE,identity_tag INTEGER NOT NULL,identity_hex TEXT NOT NULL,generation INTEGER NOT NULL,seq INTEGER NOT NULL,offset_bytes INTEGER NOT NULL,prefix_sha256 TEXT NOT NULL,sealed INTEGER NOT NULL CHECK(sealed IN (0,1)),UNIQUE(session_uuid,segment_index));
CREATE TABLE IF NOT EXISTS preview_receipts(source_uuid TEXT NOT NULL REFERENCES preview_sources(source_uuid),seq INTEGER NOT NULL,receipt_id TEXT NOT NULL UNIQUE,frame_offset INTEGER NOT NULL,body_sha256 TEXT NOT NULL,body_tsv TEXT NOT NULL,PRIMARY KEY(source_uuid,seq));
CREATE TABLE IF NOT EXISTS preview_profiles(profile_id TEXT PRIMARY KEY,body_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS preview_records(record_id TEXT PRIMARY KEY,run_id TEXT NOT NULL,segment_id TEXT,sequence INTEGER,kind TEXT NOT NULL CHECK(kind IN ('observation','event')),profile_id TEXT REFERENCES preview_profiles(profile_id),captured_at TEXT NOT NULL,source_kind TEXT NOT NULL CHECK(source_kind IN ('synthetic','agent')),body_json TEXT NOT NULL,session_uuid TEXT NOT NULL REFERENCES preview_sessions(session_uuid),ack_eligible INTEGER NOT NULL DEFAULT 0 CHECK(ack_eligible=0));
CREATE UNIQUE INDEX IF NOT EXISTS preview_run_sequence ON preview_records(run_id,sequence) WHERE kind='observation';
